head.script:
scwin.winSeq = 0;

scwin.onpageload = function() {
	windowContainer1.createWindow({
		"title" : "테스트1",
		"src" : "/sample/common_link/windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu1.xml",
		"windowId" : "window1",
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "테스트2",
		"src" : "/sample/common_link/windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu2.xml",
		"windowId" : "window2",
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "테스트3",
		"src" : "/sample/common_link/windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu3.xml",
		"windowId" : "window3",
		"frameMode" : "wframe"
	});
};

scwin.btnAddWindow_onclick = function() {
	scwin.winSeq++;
	var idx = scwin.winSeq;
	windowContainer1.createWindow({
		"title" : "신규" + idx,
		"src" : "/sample/common_link/windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu" + (((idx - 1) % 4) + 1) + ".xml",
		"windowId" : "extraWindow" + idx,
		"frameMode" : "wframe"
	});
};

scwin.windowContainer1_onwindowmaxnumexceeded = function(info) {
	windowContainer1.closeWindow(info.oldestWindowId);

	setTimeout(function() {
		windowContainer1.createWindow({
			"title" : info.title,
			"src" : info.src,
			"windowTitle" : info.windowTitle,
			"windowId" : info.windowId,
			"frameMode" : "wframe"
		});
	}, 150); // window.close 의 내부 지연(100ms) 보다 큰 값
};
